      if(bytes.length!==24+n*8||String.fromCharCode(...bytes.slice(0,4))!=='WAV1'||v.getUint16(4,true)!==1||v.getUint16(6,true)!==w||v.getUint16(8,true)!==h||v.getUint16(10,true)!==m.vectors.offset||v.getUint16(12,true)!==m.vectors.offset||v.getUint16(14,true)!==ti||v.getUint16(16,true)!==2)throw Error('invalid_current_vectors');
